package com.opspilot.incident.infrastructure.persistence;
import jakarta.persistence.*; import java.io.Serializable; import java.util.UUID;
@Entity @Table(name="incident_alerts") @IdClass(IncidentAlertEntity.Key.class) class IncidentAlertEntity { @Id @Column(name="incident_id") UUID incidentId; @Id @Column(name="alert_id") UUID alertId; protected IncidentAlertEntity(){} IncidentAlertEntity(UUID i,UUID a){incidentId=i;alertId=a;} static class Key implements Serializable { UUID incidentId; UUID alertId; public Key(){} @Override public boolean equals(Object other){return other instanceof Key key && java.util.Objects.equals(incidentId,key.incidentId)&&java.util.Objects.equals(alertId,key.alertId);}@Override public int hashCode(){return java.util.Objects.hash(incidentId,alertId);} } }
